private actor TaskControlGate {
    var waiting:CheckedContinuation<Void,Never>?,started=false
    func pause() async {started=true;await withCheckedContinuation{waiting=$0}}
    func wait() async throws {for _ in 0..<2000 {if started{return};try await Task.sleep(nanoseconds:1_000_000)};throw TaskControlMatrix.Failure(description:"Named fixture gate did not start")}
    func release(){waiting?.resume();waiting=nil}
}
/// A named local delivery fixture. It grants no production authority and calls no external service.
private actor TaskControlFixtureBackend:ConversationTaskControlBackend {
    enum Mode {case applied,lost,notFound,invalidReceipt,rejected,notSent,crashBeforeDispatch}
    var snapshot:ConversationTaskControlSnapshot
    let template:ConversationTaskControlReceipt
    var available=true,mode:Mode
    var posts:[UUID]=[],originalReads:[UUID]=[]
    var receipts:[UUID:ConversationTaskControlReceipt]=[:]
    var gate:TaskControlGate?
