    init(fixture:TaskControlServerFixture,mode:Mode = .applied){snapshot=fixture.initial.control;template=fixture.paused.operation!;self.mode=mode}
    func set(snapshot:ConversationTaskControlSnapshot?=nil,available:Bool?=nil,gate:TaskControlGate?=nil){if let snapshot {self.snapshot=snapshot};if let available {self.available=available};self.gate=gate}
    func onCommit(_ callback:@escaping @Sendable ()->Void){afterCommit=callback}
    func counts()->([UUID],[UUID]){(posts,originalReads)}
    func controlAvailability(_ reference:ConversationTaskControlReference) async throws -> Bool {available}
    func readControl(_ reference:ConversationTaskControlReference) async throws -> ConversationTaskControlEnvelope {.init(control:snapshot)}
    func submitControl(_ reference:ConversationTaskControlReference,request:ConversationTaskControlRequest) async throws -> ConversationTaskControlEnvelope {
        if mode == .notSent {throw ConversationTaskControlDispatchFailure.notSent}
        // The adapter disappears before the first transport call; no surviving not-sent proof is delivered.
        if mode == .crashBeforeDispatch {throw CancellationError()}
        posts.append(request.operationID)
        if mode == .rejected {throw CatpawError.conflict}
        let base=snapshot
        snapshot.execution_revision += 1;snapshot.task_status=request.action == .pause ? "paused" : request.action == .resume ? "scheduled":"cancelled"
        snapshot.can_pause=request.action == .resume;snapshot.can_resume=request.action == .pause;snapshot.can_revoke=request.action != .revoke;snapshot.blocked_reason=request.action == .pause ? "user_paused":request.action == .resume ? nil:"grant_changed"
        if request.action == .revoke {snapshot.authority_reference.state="revoked";snapshot.authority_reference.grant_epoch += 1;snapshot.authority_reference.delegation_revision += 1}
        snapshot.snapshot_hash=try snapshot.digest()
        var receipt=template;receipt.operation_id=request.operationID.uuidString.lowercased();receipt.action=request.action;receipt.base_execution_revision=base.execution_revision;receipt.accepted_execution_revision=snapshot.execution_revision;receipt.base_snapshot_hash=base.snapshot_hash;receipt.result_task_status=snapshot.task_status;receipt.plan_reference=base.plan_reference;receipt.receipt_hash=try receipt.digest()
        receipts[request.operationID]=receipt
        afterCommit?()
        if let gate {await gate.pause()}
        if mode == .lost || mode == .notFound {throw URLError(.networkConnectionLost)}
        if mode == .invalidReceipt {receipt.base_snapshot_hash=String(repeating:"f",count:64);receipt.receipt_hash=try receipt.digest()}
        return .init(control:snapshot,operation:receipt)
    }
    func readControlOperation(_ reference:ConversationTaskControlReference,operationID:UUID) async throws -> ConversationTaskControlEnvelope {
        originalReads.append(operationID)
        guard mode != .notFound,let receipt=receipts[operationID] else {throw ConversationTaskControlError.originalNotFound}
        return .init(control:snapshot,operation:receipt)
    }
}
private final class TaskControlFailingPersistence:SnapshotPersistence,@unchecked Sendable {
    let base:FilePersistence;private let lock=NSLock();private var fails=false
    init(url:URL){base=FilePersistence(url:url)}
    func failNext(){lock.lock();fails=true;lock.unlock()}
    func load() throws -> StoreSnapshot {try base.load()}
    func save(_ value:StoreSnapshot) throws {lock.lock();let fail=fails;fails=false;lock.unlock();if fail {throw CatpawError.unavailable("Named offline disk failure")};try base.save(value)}
}
